 using Microsoft.AspNetCore.Identity;
 using Microsoft.EntityFrameworkCore;

 namespace EquipmentTracking.Api.Data;

 public static class SeedData
 {
     public const string DemoEmail = "reviewer@equipment.local";
     public const string DemoPassword = "Review123!";

     public static async Task InitializeAsync(IServiceProvider services)
     {
         var roles = services.GetRequiredService<RoleManager<IdentityRole>>();
         foreach (var role in new[] { "Field Staff", "Office Staff", "Approver", "Manager/Admin" })
             if (!await roles.RoleExistsAsync(role)) await roles.CreateAsync(new IdentityRole(role));

         var users = services.GetRequiredService<UserManager<IdentityUser>>();
         var user = await users.FindByEmailAsync(DemoEmail);
         if (user is null)
         {
             user = new IdentityUser { UserName = DemoEmail, Email = DemoEmail, EmailConfirmed = true };
             await users.CreateAsync(user, DemoPassword);
             await users.AddToRoleAsync(user, "Manager/Admin");
         }

         var db = services.GetRequiredService<ApplicationDbContext>();
         if (!await db.Equipment.AnyAsync())
         {
             db.Equipment.AddRange(
                 Enumerable.Range(1, 4).Select(i => new Equipment { AssetId = $"TRIPOD-{i:00}", Name = "Tripod", TrackingMode = "Pooled", Total = 1, Available = 1 })
                     .Concat(Enumerable.Range(1, 6).Select(i => new Equipment { AssetId = $"TABLET-{i:00}", Name = "Field Tablet", TrackingMode = "Individual", Total = 1, Available = 1 }))
                     .Append(new Equipment { AssetId = "CAMERA-DEMO-01", Name = "Demo Camera", TrackingMode = "Individual" })
                     .Append(new Equipment { AssetId = "DRONE-001", Name = "Drone", TrackingMode = "Individual", Condition = "Restricted" }));
             await db.SaveChangesAsync();
         }
     }
 }

