 using Xunit;

 namespace EquipmentTracking.IntegrationTests;

 public class StartupTests : IClassFixture<WebApplicationFactory<Program>>
 {
     private readonly WebApplicationFactory<Program> _factory;
     public StartupTests(WebApplicationFactory<Program> factory) => _factory = factory;

     [Fact]
     public async Task Health_endpoint_is_available()
     {
         using var client = _factory.CreateClient();
         var response = await client.GetAsync("/health");
         Assert.Equal(HttpStatusCode.OK, response.StatusCode);
     }

     [Fact]
     public async Task Seed_is_repeatable_and_contains_expected_records()
     {
         using var client = _factory.CreateClient();
         var first = await client.GetStringAsync("/api/review/summary");
         var second = await client.GetStringAsync("/api/review/summary");
         Assert.Contains("\"users\":1", first);
         Assert.Contains("\"equipment\":12", first);
         Assert.Equal(first, second);
     }
 }

