 diff --git a/src/EquipmentTracking.Api/Program.cs b/src/EquipmentTracking.Api/Program.cs
 new file mode 100644
 index 0000000..673322a
 --- /dev/null
 +++ b/src/EquipmentTracking.Api/Program.cs
 @@ -0,0 +1,45 @@
 +using EquipmentTracking.Api.Data;
 +using Microsoft.AspNetCore.Identity;
 +using Microsoft.EntityFrameworkCore;
 +
 +var builder = WebApplication.CreateBuilder(args);
 +var databasePath = builder.Configuration["DatabasePath"] ?? Path.Combine(builder.Environment.ContentRootPath, "data", "equipment-tracking.db");
 +Directory.CreateDirectory(Path.GetDirectoryName(databasePath)!);
 +builder.Services.AddDbContext<ApplicationDbContext>(options => options.UseSqlite($"Data Source={databasePath}"));
 +builder.Services.AddIdentityCore<IdentityUser>(options =>
 +{
 +    options.Password.RequiredLength = 8;
 +    options.Password.RequireNonAlphanumeric = false;
 +}).AddRoles<IdentityRole>().AddEntityFrameworkStores<ApplicationDbContext>();
 +builder.Services.AddHealthChecks().AddCheck("database", () => Microsoft.Extensions.Diagnostics.HealthChecks.HealthCheckResult.Healthy());
 +builder.Services.AddEndpointsApiExplorer();
 +builder.Services.AddSwaggerGen();
 +builder.Services.AddCors(options => options.AddDefaultPolicy(policy => policy.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));
 +
 +var app = builder.Build();
 +app.UseCors();
 +app.UseDefaultFiles();
 +app.UseStaticFiles();
 +app.MapHealthChecks("/health");
 +app.MapGet("/readiness", async (ApplicationDbContext db) => Results.Ok(new { ready = await db.Database.CanConnectAsync() }));
 +app.MapGet("/api/review/summary", async (ApplicationDbContext db) => Results.Ok(new
 +{
 +    users = await db.Users.CountAsync(),
 +    roles = await db.Roles.CountAsync(),
 +    equipment = await db.Equipment.CountAsync(),
 +    approvalRules = await db.ApprovalRules.CountAsync()
 +}));
 +app.MapFallbackToFile("index.html");
 +app.UseSwagger();
 +app.UseSwaggerUI();
 +
 +using (var scope = app.Services.CreateScope())
 +{
 +    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
 +    await db.Database.MigrateAsync();
 +    await SeedData.InitializeAsync(scope.ServiceProvider);
 +}
 +
 +app.Run();
 +
 +public partial class Program { }
