 +        var second = await client.GetStringAsync("/api/review/summary");
 +        Assert.Contains("\"users\":4", first);
 +        Assert.Contains("\"equipment\":4", first);
 +        Assert.Contains("\"approvalRules\":1", first);
 +        Assert.Equal(first, second);
 +    }
